import React from "react";
import {
  BrowserRouter,
  Routes,
  Route
} from "react-router-dom";

import Sidebar from "./components/Sidebar";
import Settings from "./pages/Settings";

function App() {
  return (
    <BrowserRouter>
      <div style={styles.app}>
        <Sidebar />

        <div style={styles.content}>
          <Routes>
            <Route
              path="/"
              element={<Settings />}
            />
          </Routes>
        </div>
      </div>
    </BrowserRouter>
  );
}

const styles = {
  app: {
    display: "flex",
    background: "#0f172a",
    color: "white",
    minHeight: "100vh"
  },
  content: {
    flex: 1
  }
};

export default App;
